// Shared game-data contract. Generated by scripts/extract-data.mjs into
// data/nauvis.json from Wube's official prototype files (wube/factorio-data).
// Keys are the game's internal prototype names (e.g. "assembling-machine-2").
// Units: time in seconds, energy/power in watts (W), energy amounts in joules (J),
// fluid amounts in units, rates per second.

export interface GameData {
  /** factorio-data version the file was built from, e.g. "2.1.24". */
  version: string;
  items: Record<string, Item>;
  recipes: Record<string, Recipe>;
  /** Every placeable building the planner knows about, keyed by entity name. */
  entities: Record<string, Entity>;
  modules: Record<string, Module>;
  technologies: Record<string, Technology>;
  /** Minable resources on Nauvis (ores, crude oil). */
  resources: Record<string, Resource>;
}

export interface Item {
  name: string;
  type: 'item' | 'fluid';
  /** Human-readable name, derived from the prototype name. */
  displayName: string;
  stackSize?: number;
  /** Internal items (e.g. rocket-part) that never show in the game's menus. */
  hidden?: boolean;
  /** Entity this item places, if any. */
  placeResult?: string;
  /** Fuel value in joules. */
  fuelValue?: number;
  fuelCategory?: string;
  /** Item left behind once this fuel is burnt (uranium fuel cell → depleted cell). */
  burntResult?: string;
  /** Item group and subgroup, for browsing. */
  subgroup?: string;
  order?: string;
  /** Path inside the game files, e.g. "__base__/graphics/icons/iron-plate.png". */
  icon?: string;
  /** Link to the item's page on the official wiki. */
  wikiUrl: string;
}

export interface Ingredient {
  name: string;
  type: 'item' | 'fluid';
  amount: number;
}

export interface Product {
  name: string;
  type: 'item' | 'fluid';
  /** Expected amount per craft (already accounts for amount_min/amount_max). */
  amount: number;
  probability?: number;
  /** Fluid temperature, e.g. steam at 165 or 500. */
  temperature?: number;
  /** Part of the output that productivity bonuses do not apply to. */
  ignoredByProductivity?: number;
}

export interface Recipe {
  name: string;
  displayName: string;
  /** First of `categories`; most recipes have exactly one. */
  category: string;
  /** Machine categories that can craft it (Factorio 2.1 allows several). */
  categories: string[];
  /** Seconds per craft at crafting speed 1. */
  time: number;
  ingredients: Ingredient[];
  results: Product[];
  allowProductivity: boolean;
  /** Available without research. */
  enabledByDefault: boolean;
  subgroup?: string;
  order?: string;
  /** Maximum productivity bonus for this recipe (default 3 = +300%). */
  maximumProductivity?: number;
  /** Icon path inside the game files: the recipe's own, else its main product's. */
  icon?: string;
}

export type EntityKind =
  | 'assembler'
  | 'furnace'
  | 'chemical-plant'
  | 'refinery'
  | 'centrifuge'
  | 'rocket-silo'
  | 'lab'
  | 'mining-drill'
  | 'offshore-pump'
  | 'pump'
  | 'boiler'
  | 'generator'
  | 'solar-panel'
  | 'accumulator'
  | 'reactor'
  | 'heat-exchanger'
  | 'steam-turbine'
  | 'beacon'
  | 'belt'
  | 'underground-belt'
  | 'splitter'
  | 'inserter'
  | 'pipe'
  | 'pipe-to-ground'
  | 'storage-tank'
  | 'pole'
  | 'chest'
  | 'roboport'
  | 'rail-signal'
  | 'train-stop'
  | 'rolling-stock'
  | 'radar'
  | 'lamp'
  | 'wall'
  | 'gate'
  | 'turret'
  | 'combinator'
  | 'circuit'
  | 'heat-pipe';

export type EnergySourceType = 'electric' | 'burner' | 'heat' | 'fluid' | 'void';

export type Effect = 'speed' | 'productivity' | 'consumption' | 'pollution' | 'quality';

export interface Entity {
  name: string;
  displayName: string;
  /** Factorio prototype type, e.g. "assembling-machine". */
  prototype: string;
  kind: EntityKind;
  /** Tile footprint, before rotation. */
  width: number;
  height: number;
  /** Item used to build it. */
  item?: string;
  icon?: string;
  wikiUrl: string;

  // Crafting machines, furnaces, labs, silos
  craftingSpeed?: number;
  /** Recipe categories it can craft (crafting machines) or resource categories (drills). */
  categories?: string[];
  moduleSlots?: number;
  allowedEffects?: Effect[];
  /** Built-in productivity, e.g. 0.5 not used in base but kept for completeness. */
  baseProductivity?: number;

  // Power
  energySource?: EnergySourceType;
  /** Active power use in W (for burners: fuel burn rate in W). */
  energyUsage?: number;
  /** Constant drain in W for electric machines. */
  drain?: number;
  /** Power produced at full output in W (generators, solar, reactors). */
  powerOutput?: number;
  /** Boilers and burner devices: fraction of fuel energy converted. */
  effectivity?: number;

  // Mining
  /** Mining drill speed (resource mining time is divided by this). */
  miningSpeed?: number;
  /** Mining area side length in tiles. */
  miningArea?: number;

  // Fluids
  /** Offshore pump / pump output in units per second. */
  pumpingSpeed?: number;
  /** Fluid produced by an offshore pump. */
  fluid?: string;
  /** Boiler: steam output temperature. Generator: max temperature it uses. */
  temperature?: number;
  /** Generator / turbine fluid consumption in units per second. */
  fluidUsage?: number;
  /** Storage tank capacity. */
  fluidCapacity?: number;

  // Logistics
  /** Belt speed in items per second (both lanes). */
  beltThroughput?: number;
  /** Underground belt / pipe-to-ground max distance in tiles. */
  maxDistance?: number;
  /** Inserter rotation speed in turns per tick. */
  rotationSpeed?: number;
  /** Inserters: energy for one full turn of the arm, in J (factorio-data energy_per_rotation). */
  energyPerRotation?: number;
  /** Inserters: energy per tile the hand extends or retracts, in J. */
  energyPerMovement?: number;
  /** Bulk inserters get the bulk capacity research bonus. */
  bulk?: boolean;
  /** Electric pole supply area side length and wire reach in tiles. */
  supplyAreaDistance?: number;
  wireReach?: number;
  /** Chest inventory slots. */
  inventorySize?: number;

  // Beacons
  distributionEffectivity?: number;
  /** Beacon profile: multiplier per number of beacons affecting a machine (index 0 = 1 beacon). */
  profile?: number[];

  // Roboports (radii are half side lengths, measured from the centre)
  /** Logistics area half-size: 25 means a 50x50 orange zone. */
  logisticsRadius?: number;
  /** Construction area half-size: 55 means a 110x110 green zone. */
  constructionRadius?: number;
  /** Two roboports join one network when their squares of this half-size touch or overlap. */
  logisticsConnectionDistance?: number;

  // Rolling stock: one car takes jointDistance + connectionDistance tiles of track.
  jointDistance?: number;
  connectionDistance?: number;

  // Labs
  researchingSpeed?: number;
  inputs?: string[];
}

export interface Module {
  name: string;
  displayName: string;
  category: string;
  tier: number;
  effect: Partial<Record<Effect, number>>;
  /** Recipes it may be used with, when restricted. */
  limitation?: string[];
}

export type TechEffect =
  | { type: 'unlock-recipe'; recipe: string }
  | { type: 'mining-drill-productivity-bonus'; modifier: number }
  | { type: 'change-recipe-productivity'; recipe: string; modifier: number }
  | { type: 'laboratory-speed'; modifier: number }
  | { type: 'laboratory-productivity'; modifier: number }
  | { type: 'inserter-stack-size-bonus'; modifier: number }
  | { type: 'bulk-inserter-capacity-bonus'; modifier: number }
  | { type: 'belt-stack-size-bonus'; modifier: number }
  | { type: 'other'; name: string; modifier?: number };

export interface Technology {
  name: string;
  displayName: string;
  prerequisites: string[];
  effects: TechEffect[];
  /** Recipes this tech unlocks (same info as the unlock-recipe effects). */
  unlocksRecipes: string[];
  /** Highest level for leveled techs; "infinite" for infinite research. */
  maxLevel?: number | 'infinite';
  /** Research cost for one level. */
  cost?: { count?: number; countFormula?: string; time: number; ingredients: Ingredient[] };
  /** True when at least one effect changes production rates. */
  affectsRates: boolean;
  icon?: string;
  wikiUrl: string;
}

export interface Resource {
  name: string;
  displayName: string;
  category: string;
  /** Seconds to mine one unit at mining speed 1. */
  miningTime: number;
  results: Product[];
  /** Fluid needed to mine it (e.g. sulfuric acid for uranium). */
  requiredFluid?: string;
  fluidAmount?: number;
  /** True for crude oil style infinite resources. */
  infinite: boolean;
}
